from decimal import Decimal, ROUND_HALF_UP


def calculate_y_over_x(y: int, x: int) -> str:
    # 用 Decimal 做精确除法并四舍五入到两位，避开二进制浮点的舍入误差
    q = Decimal(y) / Decimal(x)
    return str(q.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

class Solution {
    String calculateYOverX(int y, int x) {
        return String.format("%.2f", (double) y / x);
    }
}

